const body = $input.first().json.body ?? $input.first().json;
const errors = [];
const directions = ['inbound', 'outbound'];
const statuses = ['completed', 'missed', 'failed', 'transferred'];
const intents = ['new_patient_inquiry','existing_patient','appointment_booking','appointment_reschedule','emergency','billing_insurance','general_question','other'];
const outcomes = ['booked','callback_requested','information_provided','transferred_to_staff','voicemail','no_action','lost'];
if (!body.organization_id) errors.push('organization_id is required.');
if (!body.direction || !directions.includes(String(body.direction))) errors.push('direction must be inbound or outbound.');
if (!body.caller_name || !String(body.caller_name).trim()) errors.push('caller_name is required.');
const digits = String(body.phone || '').replace(/[^0-9]/g, '');
if (digits.length < 7) errors.push('phone must include at least 7 digits.');
if (body.status && !statuses.includes(String(body.status))) errors.push('status is not a known call status.');
if (body.intent && !intents.includes(String(body.intent))) errors.push('intent is not a known call intent.');
if (body.outcome && !outcomes.includes(String(body.outcome))) errors.push('outcome is not a known call outcome.');
return [{ json: { ...body, _valid: errors.length === 0, _errors: errors } }];

function normalizePhone(raw) {
  const trimmed = String(raw).trim();
  const hasPlus = trimmed.startsWith('+');
  const digits = trimmed.replace(/[^0-9]/g, '');
  return hasPlus ? `+${digits}` : digits;
}
function capitalize(v) {
  return String(v).trim().split(/\s+/).filter(Boolean).map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
}
const b = $input.first().json;
const status = b.status || 'completed';
const noDuration = status === 'missed' || status === 'failed';
const name = capitalize(b.caller_name);
const parts = name.split(/\s+/);
return [{ json: {
  organization_id: b.organization_id,
  direction: String(b.direction).trim().toLowerCase(),
  caller_name: name,
  first_name: parts[0],
  last_name: parts.slice(1).join(' '),
  phone: normalizePhone(b.phone),
  status,
  intent: b.intent || null,
  outcome: noDuration ? null : (b.outcome || null),
  duration_seconds: noDuration ? 0 : Math.round(Number(b.duration_seconds) || 0),
  started_at: b.started_at || new Date().toISOString(),
  notes: b.notes ? String(b.notes).trim() : null,
  ai_handled: b.ai_handled === true || b.ai_handled === 'true',
  transcript: b.transcript && Array.isArray(b.transcript.lines) ? b.transcript : null
} }];

const body = $json.body ?? [];
const matches = Array.isArray(body) ? body : [];
const normalized = $('Normalize Call').item.json;
return [{ json: { ...normalized, patient_id: matches[0]?.id ?? null, found: Boolean(matches[0]) } }];

const created = ($json.body ?? [])[0];
const normalized = $('Prepare Patient').item.json;
return [{ json: { ...normalized, patient_id: created.id, found: true } }];
